function pad(n, w) { let s = String(n); while (s.length<w) s='0'+s; return s; }
export function formatTimestamp(t) {
  let s = pad(t.year,4)+'-'+pad(t.month,2)+'-'+pad(t.day,2);
  if (t.dateOnly) return s;
  s += ' '+pad(t.hour,2)+':'+pad(t.minute,2)+':'+pad(t.second,2);
  if (t.microsecond !== 0) s += '.'+pad(t.microsecond,6);
  if (t.offsetMin !== null && t.offsetMin !== undefined) {
    const a = Math.abs(t.offsetMin);
    s += (t.offsetMin < 0 ? '-' : '+') + pad(Math.floor(a/60),2)+':'+pad(a%60,2);
  }
  return s;
}
