pyFloatRepr:
```js
export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return '.nan';
  if (x === Infinity) return '.inf';
  if (x === -Infinity) return '-.inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';
  const neg = x < 0;
  const ax = Math.abs(x);
  // shortest digits via toExponential()
  const es = ax.toExponential(); // 'd.ddde±X' or 'de±X'
  // parse mantissa digits and exponent
  let epos = indexOf 'e';
  let mant = slice(0, epos), exp = Number(slice(epos+1));
  let digits = mant without '.';
  // E = exp (value = digits[0].digits[1:] × 10^E)
  let out;
  if (exp >= -4 && exp <= 15) {
    // fixed
    if (exp >= 0) {
      if (digits.length <= exp+1) out = digits + '0'*(exp+1-digits.length) + '.0';
      else out = digits.slice(0,exp+1)+'.'+digits.slice(exp+1);
    } else {
      out = '0.' + '0'*(-exp-1) + digits;
    }
  } else {
    let m = digits[0] + (digits.length>1 ? '.'+digits.slice(1) : '.0');
    let e = Math.abs(exp); let es2 = String(e); if (es2.length<2) es2='0'+es2;
    out = m + 'e' + (exp<0?'-':'+') + es2;
  }
  return neg ? '-'+out : out;
}
