export function escapeDoubleQuoted(s) {
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    const esc = ESCAPES[cp]; // or switch
    if (esc) { out += esc; continue; }
    if (cp >= 0x20 && cp <= 0x7E) { out += ch; continue; }
    if (cp <= 0xFF) out += '\\x' + hex(cp,2);
    else if (cp <= 0xFFFF) out += '\\u' + hex(cp,4);
    else out += '\\U' + hex(cp,8);
  }
  return out;
}
